    const y=finishing&&critical?clamp((Number(view.y)||view.height*.56)/Math.max(1,view.height)-.17,.12,.64):-.08;
    const entity=this.forceSpawn('restoration',{x,y,vx:0,vy:.055,scale:1,spin:.18});
