  font*=Math.max(.1,fit);college.style.fontSize=font+'px';cm=metrics(college,'SPACE MUSIC COLLEGE');
  const spacing=Math.max(0,Math.min(font*.4,(available-cm.width)/19));college.style.letterSpacing=spacing+'px';
