 const controls=make('div',null,'skill-atlas-controls');controls.append(action('−',()=>zoomBy(.86)),action('+',()=>zoomBy(1.16)),action(t('Сверху','Overhead'),()=>{pitch=1.28;vy=0;dirty=true;}),action(t('Центр','Reset'),resetView));controls.children[0].setAttribute('aria-label',t('Отдалить','Zoom out'));controls.children[1].setAttribute('aria-label',t('Приблизить','Zoom in'));root.append(controls);
 const index=make('aside',null,'skill-atlas-index');index.hidden=true;const search=make('input');search.type='search';search.placeholder=t('Найти лад','Find a scale');search.setAttribute('aria-label',search.placeholder);const indexItems=make('div',null,'skill-atlas-index-items');index.append(search,indexItems);root.append(index);
 const listToggle=action(t('Все лады','All scales'),()=>{index.hidden=!index.hidden;listToggle.setAttribute('aria-expanded',String(!index.hidden));if(!index.hidden)search.focus();},'skill-atlas-list-toggle');listToggle.setAttribute('aria-expanded','false');root.append(listToggle);
 const detail=make('aside',null,'skill-atlas-detail');detail.hidden=true;detail.setAttribute('aria-label',t('О выбранном навыке','Selected skill'));root.append(detail);
